import math

def check_bound(N):
    max_f = 2**N
    print(f"For N={N}, max possible value for f(T) is 2^{N} = {max_f}")

for N in [1, 2, 3, 4]:
    check_bound(N)

import itertools

# S = {1, 2}. Subsets are: T0={}, T1={1}, T2={2}, T12={1, 2}
# We iterate over 16 colorings. A coloring is defined by the color of these 4 subsets.
# c_T = 1 if T is blue, 0 if T is green.
# Index mapping: 0 -> T0, 1 -> T1, 2 -> T2, 3 -> T12

subsets = [
    set(),
    {1},
    {2},
    {1, 2}
]

solution_count = 0

for coloring_tuple in itertools.product([0, 1], repeat=4):
    # coloring_tuple = (c_T0, c_T1, c_T2, c_T12)

    colors = {}
    for i in range(4):
        colors[subsets[i]] = coloring_tuple[i]

    # Step 2: Calculate f(T) for all T in 2^S
    f = {}

    # T0 = {}
    f[set()] = colors[set()]

    # T1 = {1}
    f[{1}] = colors[set()] + colors[{1}]

    # T2 = {2}
    f[{2}] = colors[set()] + colors[{2}]

    # T12 = {1, 2}
    f[{1, 2}] = colors[set()] + colors[{1}] + colors[{2}] + colors[{1, 2}]

    # Step 3: Verify the condition f(T1)f(T2) = f(T1 U T2)f(T1 n T2)
    is_solution = True

    # We check all pairs (T1, T2) where T1 <= T2 in terms of structure for efficiency, 
    # but we must ensure all 10 pairs are covered. 

    # Iterate over all pairs of subsets (T1, T2)
    for T1 in subsets:
        for T2 in subsets:

            # Intersection and Union
            T_intersect = T1.intersection(T2)
            T_union = T1.union(T2)

            # Check the functional equation
            lhs = f[T1] * f[T2]
            rhs = f[T_union] * f[T_intersect]

            if lhs != rhs:
                is_solution = False
                break
        if not is_solution:
            break

    if is_solution:
        solution_count += 1

print(f"Total number of solutions found for N=2: {solution_count}")

count = 0
for c0 in [0, 1]:
    for c1 in [0, 1]:
        for c2 in [0, 1]:
            for c12 in [0, 1]:
                if c1 * c2 == c12 * c0:
                    count += 1
print(count)
